    state text NOT NULL,
    reason text,
    changed_by text,
    changed_at timestamp with time zone NOT NULL,
    CONSTRAINT account_lifecycle_state_check CHECK ((state = ANY (ARRAY['active'::text, 'locked'::text, 'suspended'::text, 'deactivated'::text, 'erasure_pending'::text])))
