    accept_third_party_mention boolean DEFAULT false NOT NULL,
    act_on_behalf boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT agent_participation_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['realm'::text, 'circle'::text, 'strand'::text])))
);

CREATE TABLE public.agent_participation_ceiling (
    scope_kind text NOT NULL,
    id text NOT NULL,
    realm_id uuid NOT NULL,
    reply boolean DEFAULT false NOT NULL,
    accept_third_party_mention boolean DEFAULT false NOT NULL,
    act_on_behalf boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT agent_participation_ceiling_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['realm'::text, 'circle'::text, 'strand'::text])))
);

CREATE TABLE public.agent_principals (
    id text NOT NULL,
    controller_id text NOT NULL,
    principal_control_realm_id text NOT NULL,
    controller_authorization_ref text NOT NULL,
    display_name text,
    agent_slug text,
    avatar_blob_ref text,
    state text DEFAULT 'active'::text NOT NULL,
    requested_scope jsonb,
    accountability jsonb,
    provision_event_refs jsonb,
    pairing_request_id text,
    paired_pairing_request_id text,
    paired_request_digest text,
    pairing_code text,
    pairing_expires_at timestamp with time zone,
    approval_request_id text,
    controller_account_id uuid,
    recipient_service_id text,
    runtime_key_binding_digest text,
    runtime_public_key_digest text,
    runtime_attestation_digest text,
    approval_notification_id uuid,
    runtime_key_request jsonb,
    approval_requested_at timestamp with time zone,
    authorized_event_ref text,
    authorized_verification_method text,
    authorized_public_key_digest text,
    state_changed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT agent_principals_id_check CHECK (((id ~~ 'did:%'::text) AND (id !~ '[[:space:]#?]'::text))),
    CONSTRAINT agent_principals_pcr_id_check CHECK ((principal_control_realm_id ~ '^ak:realm:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT agent_principals_controller_authorization_ref_check CHECK ((controller_authorization_ref ~~ (id || '#%'::text))),
    CONSTRAINT agent_principals_agent_slug_check CHECK ((agent_slug IS NULL) OR ((char_length(agent_slug) BETWEEN 1 AND 64) AND (octet_length(agent_slug) <= 256) AND (agent_slug !~ '[[:space:][:cntrl:]]'::text) AND (strpos(agent_slug, ':'::text) = 0) AND (strpos(agent_slug, '@'::text) = 0) AND (strpos(agent_slug, '/'::text) = 0) AND (strpos(agent_slug, '#'::text) = 0) AND (strpos(agent_slug, '?'::text) = 0) AND (strpos(agent_slug, E'\\') = 0))),
    CONSTRAINT agent_principals_state_check CHECK ((state = ANY (ARRAY['pending_runtime_key'::text, 'active'::text, 'paused'::text, 'deactivated'::text, 'pairing_expired'::text])))
);

CREATE TABLE public.agent_sidecars (
